function famousCompanies(){const byCode=new Map(Object.values(factoryData).flat().map(factory=>[factory.code,factory]));return famousCompanyCodes.map(code=>byCode.get(code)).filter(Boolean)}
function marketMultiplier(code){const delivered=Number(marketCounts[code])||0;return Math.max(.75,Math.min(1.25,1.25-delivered*.05))}
function marketReward(km,code){const base=reward(km),factor=marketMultiplier(code);return{pay:Math.round(base.pay*factor),xp:base.xp,factor}}
function dailyOffersForCity(city){const destinations=(routes[city]||[]).filter(route=>route.km<=100),companies=famousCompanies(),key=missionPeriodKeys().daily,random=offerRandom('ofertas-'+key+'-'+city),shuffle=list=>[...list].sort(()=>random()-.5),pickedRoutes=shuffle(destinations),pickedCompanies=shuffle(companies);return Array.from({length:3},(_,index)=>{const route=pickedRoutes[index%pickedRoutes.length],company=pickedCompanies[index%pickedCompanies.length],items=company.products.split(',').map(item=>item.trim()),cargo=items[Math.floor(random()*items.length)]+' para operação regional';return{...route,company,cargo,offerKey:key,index}})}

function companyLogo(factory,small=false){const file=brandFiles[factory.code],brand=brandIds[factory.code];if(file)return'<div class="factory-brand local-brand '+(small?'small':'')+'"><img src="assets/brands/'+file+'" alt="Logo '+factory.name+'"></div>';if(brand)return'<svg class="factory-brand '+(small?'small':'')+'" role="img" aria-label="Logo '+factory.name+'"><use href="assets/brands/factory-logos.svg#'+brand+'"></use></svg>';return'<div class="factory-brand factory-initial '+(small?'small':'')+'">'+escapeHTML(factory.code)+'</div>'}
function companyLogoByName(name){const factory=Object.values(factoryData).flat().find(item=>item.name===name);if(!factory)return'';const file=brandFiles[factory.code],brand=brandIds[factory.code];if(file)return'<span class="status-company-logo local-brand"><img src="assets/brands/'+file+'" alt="Logo '+factory.name+'"></span>';if(brand)return'<svg class="status-company-logo" role="img" aria-label="Logo '+factory.name+'"><use href="assets/brands/factory-logos.svg#'+brand+'"></use></svg>';return'<span class="status-company-logo factory-initial">'+escapeHTML(factory.code)+'</span>'}
