function missionCard(mission,reward){const pct=Math.min(100,Math.round((mission.progress/mission.target)*100));return'<article class="mission-card '+(mission.claimed?'done':'')+'"><header><span>'+(mission.claimed?'CONCLUÍDA':'EM ANDAMENTO')+'</span><b>+'+reward+' PT'+(reward>1?'S':'')+'</b></header><h3>'+escapeHTML(mission.title)+'</h3><p>'+escapeHTML(mission.description)+'</p><div class="mission-progress"><i style="width:'+pct+'%"></i></div><small>'+mission.progress+' / '+mission.target+' CONCLUÍDO'+(mission.target>1?'S':'')+'</small></article>'}
function missionsPage(){if(ensureMissions())save();const weekly=missionTab==='weekly',list=state.missions[weekly?'weekly':'daily'],remain=nextMissionReset(weekly?'weekly':'daily');$('#view').innerHTML=heading('DESAFIOS DA ESTRADA','Missões','Complete objetivos de entrega e dispute o ranking de pontos.')+'<div class="mission-summary"><div><span>SEUS PONTOS DE MISSÃO</span><b>'+state.missionPoints+'</b></div><small>'+(weekly?'REINÍCIO NA PRÓXIMA QUARTA-FEIRA':'REINÍCIO À MEIA-NOITE')+' · HORÁRIO DE BRASÍLIA<br><strong>'+formatTime(remain)+'</strong> restantes</small></div><nav class="page-tabs"><button data-mission-tab="daily" class="'+(!weekly?'active':'')+'">MISSÕES DIÁRIAS</button><button data-mission-tab="weekly" class="'+(weekly?'active':'')+'">MISSÕES SEMANAIS</button></nav><section class="mission-grid">'+list.map(item=>missionCard(item,weekly?5:1)).join('')+'</section>';document.querySelectorAll('[data-mission-tab]').forEach(button=>button.onclick=()=>{missionTab=button.dataset.missionTab;missionsPage()})}function profile(){const p=progress(),name=user.displayName||'Motorista';$('#view').innerHTML=heading('CARTEIRA PROFISSIONAL','Meu perfil','Seu histórico e evolução como motorista.')+'<div class="profile-grid"><aside class="panel identity"><img class="avatar" src="'+(user.photoURL||avatar(name))+'" alt=""><h2>'+name+'</h2><p>REGISTRO RL-'+user.uid.slice(0,8).toUpperCase()+'</p><div class="profile-data"><div><span>Localização atual</span><b>'+state.city+', SP</b></div><div><span>Saldo</span><b>'+money(state.balance)+'</b></div><div><span>Entregas</span><b>'+state.deliveries+'</b></div><div><span>Distância</span><b>'+state.km+' km</b></div></div><button class="logout-button" type="button" data-logout>SAIR DA CONTA</button></aside><section class="panel profile-main"><h2>PROGRESSÃO DO MOTORISTA</h2><div class="level-row"><div><span>NÍVEL ATUAL</span><b>'+p.l+'</b></div><span>'+p.now+' / '+p.need+' XP</span></div><div class="xpbar"><i style="width:'+p.pct+'%"></i></div><div class="progress-label"><span>'+p.pct+'% concluído</span><span>Progressão infinita e lenta</span></div><div class="milestones"><h2>PLANO DE CARREIRA</h2><div class="milestone done"><i></i><div><b>Motorista contratado</b><small>Entregas com veículo fornecido pela empresa.</small></div></div><div class="milestone '+(p.l>=10?'done':'')+'"><i></i><div><b>Comprar o primeiro caminhão · Nível 10</b><small>Tenha seu veículo e receba uma parcela maior do frete.</small></div></div><div class="milestone '+(p.l>=25?'done':'')+'"><i></i><div><b>Abrir transportadora · Nível 25</b><small>Contrate motoristas e administre sua própria empresa.</small></div></div></div></section></div>';document.querySelector('[data-logout]').onclick=logout}
function financialEntries(){const entries=[...(Array.isArray(state.ledger)?state.ledger:[])],refs=new Set(entries.map(item=>item.ref).filter(Boolean));(state.history||[]).forEach((trip,index)=>{const ref=trip.id?'delivery-'+trip.id:'legacy-delivery-'+index;if(!refs.has(ref))entries.push({id:ref,type:'credit',amount:Number(trip.pay)||0,title:'Pagamento de entrega',details:(trip.company?trip.company+' · ':'')+(trip.from||'?')+' → '+(trip.to||'?')+' · '+(trip.km||0)+' km',at:trip.at||0,ref,legacy:true})});if(state.loan&&state.loan.principal&&!entries.some(item=>item.ref==='loan-credit'))entries.push({id:'legacy-loan',type:'credit',amount:Number(state.loan.principal)||45000,title:'Empréstimo bancário',details:'Crédito recuperado do contrato atual.',at:0,ref:'loan-credit',legacy:true});if(state.truck==='agrale8500'&&!entries.some(item=>item.ref==='truck-agrale'))entries.push({id:'legacy-truck',type:'debit',amount:50000,title:'Compra do Agrale 8500',details:'Aquisição recuperada do patrimônio da conta.',at:0,ref:'truck-agrale',legacy:true});return entries.sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0))}
function balancePage(){const entries=financialEntries(),income=entries.filter(item=>item.type==='credit').reduce((sum,item)=>sum+item.amount,0),expense=entries.filter(item=>item.type==='debit').reduce((sum,item)=>sum+item.amount,0),formatDate=at=>at?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(at)):'REGISTRO ANTIGO';$('#view').innerHTML=heading('CONTROLE FINANCEIRO','Saldo','Veja de onde o dinheiro entrou, onde foi gasto e o histórico recuperado da sua carreira.')+'<section class="balance-summary"><article><span>SALDO DISPONÍVEL</span><b>'+money(state.balance)+'</b><small>Valor atual da conta</small></article><article><span>TOTAL DE ENTRADAS</span><b class="credit">+'+money(income)+'</b><small>'+entries.filter(item=>item.type==='credit').length+' movimentações recuperadas</small></article><article><span>TOTAL DE SAÍDAS</span><b class="debit">-'+money(expense)+'</b><small>'+entries.filter(item=>item.type==='debit').length+' movimentações recuperadas</small></article></section><section class="statement"><header><div><p class="eyebrow">EXTRATO DA CARREIRA</p><h2>Histórico do saldo</h2></div><span>'+entries.length+' LANÇAMENTOS</span></header><div class="statement-list">'+(entries.length?entries.map(item=>'<article class="statement-row '+item.type+'"><i>'+(item.type==='credit'?'↗':'↙')+'</i><div><b>'+escapeHTML(item.title)+'</b><p>'+escapeHTML(item.details||'Movimentação da conta')+'</p><small>'+formatDate(item.at)+(item.legacy?' · HISTÓRICO RECUPERADO':'')+'</small></div><strong>'+(item.type==='credit'?'+':'-')+money(item.amount)+'</strong></article>').join(''):'<div class="statement-empty">Nenhuma movimentação registrada ainda.</div>')+'</div></section>'}
function truckPage(){const vehicle={name:'O Velho Companheiro',year:'1994',odometer:'684.230 km',range:'100 km',condition:'Usado · operacional'};$('#view').innerHTML=heading('VEÍCULO ATUAL','Meu caminhão','O primeiro capítulo da sua história na estrada.')+'<section class="truck-page"><div class="inherited-truck"><img src="assets/trucks/caminhao-herdado.png" alt="Caminhão antigo e usado emprestado pela tia do jogador"><span>EMPRESTADO PELA SUA TIA</span></div><aside class="truck-story"><p class="eyebrow">UMA CHANCE EM FAMÍLIA</p><h2>'+vehicle.name+'</h2><p>Este caminhão pertenceu ao seu tio, um caminhoneiro que passou boa parte da vida cruzando as estradas do Brasil. Depois que ele faleceu, sua tia guardou o veículo por algum tempo. Sabendo que você queria começar uma carreira, ela decidiu emprestá-lo para que o velho companheiro voltasse à estrada.</p><p>O acordo é simples: você cuida do caminhão e paga <strong>R$ 700,00 por semana</strong> pelo empréstimo. Assim poderá juntar dinheiro e, no futuro, comprar seu próprio veículo.</p><dl><div><dt>PROPRIETÁRIA</dt><dd>Sua tia</dd></div><div><dt>COBRANÇA</dt><dd>Todo sábado</dd></div><div><dt>ALUGUEL SEMANAL</dt><dd>'+money(700)+'</dd></div><div><dt>ANO</dt><dd>'+vehicle.year+'</dd></div><div><dt>QUILOMETRAGEM</dt><dd>'+vehicle.odometer+'</dd></div><div><dt>CONDIÇÃO</dt><dd>'+vehicle.condition+'</dd></div><div class="range-row"><dt>ALCANCE MÁXIMO</dt><dd>'+vehicle.range+'</dd></div></dl><div class="truck-warning"><b>ALCANCE LIMITADO</b><span>Contratos acima de 100 km não aparecem no mercado enquanto este for seu caminhão.</span></div><button data-jobs>PROCURAR TRABALHOS</button></aside></section>';bind()}
function rankingList(players,type){const value=player=>type==='money'?Number(player.balance)||0:type==='km'?Number(player.km)||0:type==='missions'?Number(player.missionPoints)||0:Number(player.level)||1,sorted=[...players].sort((a,b)=>value(b)-value(a));return sorted.length?sorted.slice(0,50).map((player,index)=>'<article class="rank-player '+(player.uid===user.uid?'is-you':'')+'"><b class="rank-position">'+(index+1)+'</b><img src="'+(player.photo||avatar(player.name))+'" alt=""><div><strong>'+escapeHTML(player.name)+(player.uid===user.uid?' (você)':'')+'</strong><small>'+escapeHTML(player.city)+', SP · '+escapeHTML(player.status||'Offline')+'</small></div><span>'+(type==='money'?money(value(player)):type==='km'?value(player).toLocaleString('pt-BR')+' km':type==='missions'?value(player)+' pts':'Nível '+value(player))+'</span></article>').join(''):'<p class="ranking-empty">Nenhum motorista registrado ainda.</p>'}
function ranking(){const current={uid:user.uid,name:user.displayName||'Motorista',photo:user.photoURL||'',level:level(state.xp),balance:state.balance,km:state.km,missionPoints:Number(state.missionPoints)||0,city:state.city,status:state.trip?'Em viagem':'Online'},players=allPlayers.some(player=>player.uid===user.uid)?allPlayers.map(player=>player.uid===user.uid?{...player,...current}:player):[current,...allPlayers],boards={money:{tag:'FORTUNAS DA ESTRADA',title:'Mais dinheiro',icon:'R$'},level:{tag:'LENDAS DO ASFALTO',title:'Maior nível',icon:'XP'},km:{tag:'REIS DA RODOVIA',title:'Maior distância',icon:'KM'},missions:{tag:'DESAFIOS CONCLUÍDOS',title:'Pontos de missão',icon:'PTS'}},board=boards[rankingTab]||boards.money;$('#view').innerHTML=heading('CARREIRA COMPETITIVA','Ranking dos motoristas','Escolha uma categoria para comparar sua carreira com os demais jogadores.')+'<nav class="page-tabs ranking-tabs"><button data-ranking-tab="money" class="'+(rankingTab==='money'?'active':'')+'">DINHEIRO</button><button data-ranking-tab="level" class="'+(rankingTab==='level'?'active':'')+'">NÍVEL</button><button data-ranking-tab="km" class="'+(rankingTab==='km'?'active':'')+'">DISTÂNCIA</button><button data-ranking-tab="missions" class="'+(rankingTab==='missions'?'active':'')+'">MISSÕES</button></nav><section class="ranking-single"><div class="ranking-board '+(rankingTab==='missions'?'mission-ranking':'')+'"><header><div><span>'+board.tag+'</span><h2>'+board.title+'</h2></div><b>'+board.icon+'</b></header><div class="ranking-list">'+rankingList(players,rankingTab)+'</div></div></section>';document.querySelectorAll('[data-ranking-tab]').forEach(button=>button.onclick=()=>{rankingTab=button.dataset.rankingTab;ranking()})}
function truckPageV2(){const truck=currentTruck(),borrowed=state.truck!=='agrale8500';$('#view').innerHTML=heading('VEÍCULO ATUAL','Meu caminhão',borrowed?'O caminhão emprestado que iniciou sua carreira.':'Seu primeiro caminhão próprio.')+'<section class="truck-page"><div class="inherited-truck"><img src="'+truck.image+'" alt="'+truck.name+'"><span>'+(borrowed?'EMPRESTADO PELA SUA TIA':'VEÍCULO PRÓPRIO')+'</span></div><aside class="truck-story"><p class="eyebrow">'+(borrowed?'UMA CHANCE EM FAMÍLIA':'PATRIMÔNIO DO MOTORISTA')+'</p><h2>'+truck.name+'</h2><p>'+(borrowed?'Depois que seu tio faleceu, sua tia emprestou o antigo caminhão para você começar. O acordo custa R$ 700,00 por semana e termina quando você compra seu próprio veículo.':'O Agrale 8500 é compacto, robusto e adequado a entregas urbanas e pequenos trechos rodoviários. Sua capacidade maior aumenta o pagamento dos fretes em 45%.')+'</p><dl><div><dt>PROPRIEDADE</dt><dd>'+(borrowed?'Sua tia':'Sua')+'</dd></div><div><dt>CAPACIDADE DE CARGA</dt><dd>'+truck.capacity.toLocaleString('pt-BR')+' kg</dd></div><div><dt>ALCANCE OPERACIONAL</dt><dd>'+truck.range+' km</dd></div><div><dt>MULTIPLICADOR DE FRETE</dt><dd>'+truck.multiplier.toFixed(2).replace('.',',')+'x</dd></div>'+(borrowed?'<div><dt>ALUGUEL</dt><dd>'+money(700)+' / semana</dd></div>':'<div><dt>MODELO</dt><dd>Agrale 8500 · 4x2</dd></div>')+'</dl><div class="truck-warning"><b>CAPACIDADE E RENDA</b><span>Quanto maior a capacidade útil, maior o valor pago pelas empresas em cada frete.</span></div><button data-jobs>PROCURAR TRABALHOS</button></aside></section>';bind()}
const baseTruckPageV2=truckPageV2;truckPageV2=function(){baseTruckPageV2();if(state.truck!=='agrale8500'){const warning=document.querySelector('.truck-warning');warning?.insertAdjacentHTML('beforebegin','<div class="rental-exemption"><b>PRIMEIRO SÁBADO ISENTO</b><span>A primeira cobrança semanal do caminhão não será descontada.</span></div>')}};
const loanPlans={8:{rate:.08},16:{rate:.18},24:{rate:.30},36:{rate:.48}};function loanQuote(weeks){const plan=loanPlans[weeks],total=Math.round(45000*(1+plan.rate)),weekly=Math.ceil(total/weeks);return{weeks:+weeks,rate:plan.rate,total,weekly}}
function truckShop(){const owned=state.truck==='agrale8500',truck=truckCatalog.agrale8500;$('#view').innerHTML=heading('CONCESSIONÁRIA LONER','Venda de caminhões','Compre veículos para aumentar sua capacidade e o valor dos fretes.')+'<section class="dealer-card"><div class="dealer-photo"><img src="'+truck.image+'" alt="Agrale 8500 com carroceria baú"><span>SEMINOVO</span></div><div class="dealer-info"><p class="eyebrow">CAMINHÃO LEVE · 4X2</p><h2>Agrale 8500</h2><strong class="dealer-price">'+money(truck.price)+'</strong><p>Caminhão compacto para distribuição urbana e trajetos rodoviários curtos. Equipado com carroceria baú para cargas secas.</p><dl><div><dt>CAPACIDADE ÚTIL</dt><dd>'+truck.capacity.toLocaleString('pt-BR')+' kg</dd></div><div><dt>ALCANCE NO JOGO</dt><dd>'+truck.range+' km</dd></div><div><dt>BÔNUS NOS FRETES</dt><dd>+45%</dd></div><div><dt>PBT DA LINHA</dt><dd>8.500 kg</dd></div></dl><button data-buy-truck '+(owned?'disabled':'')+'>'+(owned?'VEÍCULO JÁ ADQUIRIDO':'COMPRAR POR '+money(truck.price))+'</button><small>Seu saldo atual: '+money(state.balance)+'</small></div></section>';document.querySelector('[data-buy-truck]')?.addEventListener('click',buyAgrale)}
function buyAgrale(){if(state.truck==='agrale8500')return;if(state.balance<50000){toast('Saldo insuficiente para comprar o Agrale 8500.');return}state.balance-=50000;state.truck='agrale8500';addLedger('debit',50000,'Compra do Agrale 8500','Caminhão próprio registrado na sua transportadora.',Date.now(),'truck-agrale');save();toast('Agrale 8500 comprado! O aluguel da sua tia foi encerrado.');truckShop()}
function bankPage(){const active=state.loan?.active,quote=loanQuote(8);$('#view').innerHTML=heading('BANCO LONER','Crédito para crescer','Financiamento semanal para comprar seu primeiro caminhão.')+(active?'<section class="loan-active"><p class="eyebrow">EMPRÉSTIMO ATIVO</p><h2>'+money(state.loan.remainingBalance)+'</h2><span>SALDO DEVEDOR</span><div><b>'+state.loan.remainingWeeks+'</b><small>PARCELAS RESTANTES</small></div><div><b>'+money(state.loan.weekly)+'</b><small>TODO SÁBADO</small></div><p>As parcelas são cobradas mesmo quando seu saldo estiver insuficiente.</p></section>':'<section class="bank-offer"><div><p class="eyebrow">CRÉDITO PRÉ-APROVADO</p><h2>'+money(45000)+'</h2><p>Escolha o prazo. Quanto maior o número de semanas, maiores serão os juros totais.</p></div><aside><label for="loan-weeks">PRAZO DE PAGAMENTO</label><select id="loan-weeks"><option value="8">8 semanas · 8% de juros</option><option value="16">16 semanas · 18% de juros</option><option value="24">24 semanas · 30% de juros</option><option value="36">36 semanas · 48% de juros</option></select><dl><div><dt>VALOR RECEBIDO</dt><dd>'+money(45000)+'</dd></div><div><dt>TOTAL A PAGAR</dt><dd id="loan-total">'+money(quote.total)+'</dd></div><div><dt>PARCELA SEMANAL</dt><dd id="loan-weekly">'+money(quote.weekly)+'</dd></div></dl><button data-take-loan>CONTRATAR EMPRÉSTIMO</button><small>Débito automático todos os sábados. O saldo poderá ficar negativo.</small></aside></section>');const select=$('#loan-weeks');if(select)select.onchange=()=>{const q=loanQuote(select.value);$('#loan-total').textContent=money(q.total);$('#loan-weekly').textContent=money(q.weekly)};document.querySelector('[data-take-loan]')?.addEventListener('click',takeLoan)}
function takeLoan(){if(state.loan?.active)return;const q=loanQuote($('#loan-weeks').value),p=brazilNow(),today=p.year+'-'+p.month+'-'+p.day;state.balance+=45000;state.loan={active:true,principal:45000,total:q.total,weekly:q.weekly,remainingBalance:q.total,remainingWeeks:q.weeks,rate:q.rate,paidOn:p.weekday==='Sat'?today:''};addLedger('credit',45000,'Empréstimo bancário',q.weeks+' parcelas semanais · total contratado '+money(q.total),Date.now(),'loan-credit');save();toast('Empréstimo aprovado: '+money(45000)+' adicionados ao saldo.');bankPage()}
function companyPage(){if(!state.companyName){$('#view').innerHTML=heading('SEU PRÓXIMO PASSO','Criar minha empresa','Escolha o nome definitivo da sua transportadora para abrir a página dela.')+'<section class="company-create"><div class="company-create-mark">RL</div><div><p class="eyebrow">FUNDAÇÃO DA TRANSPORTADORA</p><h2>Dê um nome ao seu futuro</h2><p>O nome será registrado nesta conta e aparecerá na página da sua empresa.</p><form id="company-form"><label for="company-name">NOME DA EMPRESA</label><input id="company-name" maxlength="32" minlength="3" autocomplete="organization" placeholder="Ex.: Horizonte Transportes" required><small>Use de 3 a 32 caracteres.</small><button type="submit">CRIAR MINHA EMPRESA</button></form></div></section>';$('#company-form').onsubmit=event=>{event.preventDefault();const name=$('#company-name').value.trim().replace(/\s+/g,' ');if(name.length<3){toast('Digite um nome com pelo menos 3 caracteres.');return}state.companyName=name.slice(0,32);save();toast('Transportadora criada com sucesso!');companyPage()};return}const ownedTrucks=state.truck==='agrale8500'?1:0,name=escapeHTML(state.companyName),initials=state.companyName.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();$('#view').innerHTML=heading('GESTÃO DA TRANSPORTADORA',name,'Acompanhe o patrimônio e o crescimento da sua empresa.')+'<section class="company-dashboard"><header><div class="company-emblem">'+escapeHTML(initials)+'</div><div><span>TRANSPORTADORA DO JOGADOR</span><h2>'+name+'</h2><p>Fundador: '+escapeHTML(user.displayName||'Motorista')+'</p></div></header><div class="company-stats"><article><span>CAMINHÕES REGISTRADOS</span><b>'+ownedTrucks+'</b><small>Somente veículos próprios entram na frota</small></article><article><span>MOTORISTAS CONTRATADOS</span><b>0</b><small>Você ainda trabalha sozinho</small></article><article><span>QUILÔMETROS DA EMPRESA</span><b>'+Number(state.km).toLocaleString('pt-BR')+'</b><small>km percorridos pelo fundador</small></article></div><div class="company-fleet"><div><p class="eyebrow">FROTA DA EMPRESA</p><h3>'+(ownedTrucks?'1 caminhão registrado':'Nenhum caminhão registrado')+'</h3><p>'+(ownedTrucks?'Seu Agrale 8500 está registrado no patrimônio da transportadora.':'O caminhão da sua tia é emprestado e não pertence à empresa. Compre um veículo próprio para iniciar a frota.')+'</p></div><button data-company-shop>VER CAMINHÕES À VENDA</button></div></section>';document.querySelector('[data-company-shop]').onclick=()=>location.hash='concessionaria'}
function updateOfferClock(){const remain=nextMissionReset('daily'),total=Math.max(0,Math.floor(remain/1000)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),seconds=total%60,display=$('#offer-reset'),validUntil=$('#offer-valid-until');if(display)display.textContent=String(hours).padStart(2,'0')+':'+String(minutes).padStart(2,'0')+':'+String(seconds).padStart(2,'0');if(validUntil)validUntil.textContent=nextOfferHour();if(location.hash==='#entregas'&&activeOfferKey&&activeOfferKey!==offerCycleKey())deliveries()}
